const fs = require('fs');
const path = require('path');

const ROOT = '/factory-os/klanten/fumero/kennisbank';
const listPath = path.join(ROOT, '_startset_urls.json');

function slugForUrl(u) {
  try {
    const x = new URL(u);
    const host = (x.hostname || 'site').replace(/\./g, '_');
    let p = (x.pathname || '/').replace(/^\/+|\/+$/g, '').replace(/\//g, '__');
    if (!p) p = 'root';
    p = p.replace(/[^\w-]+/g, '_');
    return host + '__' + p;
  } catch (e) {
    return 'invalid';
  }
}

let URLS;
try {
  URLS = JSON.parse(fs.readFileSync(listPath, 'utf8')).urls;
} catch (e) {
  URLS = ['https://fumero.nl/'];
}
if (!Array.isArray(URLS) || !URLS.length) URLS = ['https://fumero.nl/'];

const key = ($env.JINA_API_KEY || '').trim();
const results = [];

for (const target of URLS) {
  const jinaUrl = 'https://r.jina.ai/' + target;
  const headers = {
    Accept: 'text/plain',
    'User-Agent': 'Mozilla/5.0 (compatible; Factory-OS-Bibliothecaris/1.0)',
  };
  if (key) headers.Authorization = 'Bearer ' + key;
  try {
    const res = await fetch(jinaUrl, { headers, signal: AbortSignal.timeout(120000) });
    if (!res.ok) {
      results.push({ url: target, ok: false, error: 'HTTP ' + res.status });
      continue;
    }
    const body = await res.text();
    const slug = slugForUrl(target);
    const fetched = new Date().toISOString();
    const front = '---\nsource_url: ' + target + '\nfetched_at: ' + fetched + '\nreader: jina\n---\n\n';
    fs.mkdirSync(ROOT, { recursive: true });
    fs.writeFileSync(path.join(ROOT, slug + '.md'), front + body, 'utf8');
    results.push({ url: target, file: slug + '.md', ok: true });
  } catch (e) {
    results.push({ url: target, ok: false, error: String(e.message || e) });
  }
}

return [{
  json: {
    ok_count: results.filter((r) => r.ok).length,
    fail_count: results.filter((r) => !r.ok).length,
    results,
    root: ROOT,
  },
}];

